<?php require_once '../includes/auth.php'; require_role(['admin','supplier']); $page_title='Products'; $uid=(int)$_SESSION['user_id'];
if(isset($_POST['add'])){ $name=clean($conn,$_POST['name']); $sku=clean($conn,$_POST['sku']); $barcode=clean($conn,$_POST['barcode']); $cat=(int)$_POST['category_id']; $pp=(float)$_POST['purchase_price']; $sp=(float)$_POST['sale_price']; $gst=(float)$_POST['gst_percent']; $supplier_id=$_SESSION['role']=='supplier'?$uid:(int)$_POST['supplier_id']; mysqli_query($conn,"INSERT INTO products(name,sku,barcode,category_id,purchase_price,sale_price,gst_percent,created_by,supplier_id) VALUES('$name','$sku','$barcode',$cat,$pp,$sp,$gst,$uid,$supplier_id)"); log_audit($conn,$uid,'Add Product',$name); redirect('products.php'); }
include '../includes/header.php'; include '../includes/sidebar.php'; $cats=mysqli_query($conn,"SELECT * FROM categories"); $suppliers=mysqli_query($conn,"SELECT * FROM users WHERE role='supplier'"); $where=$_SESSION['role']=='supplier'?"WHERE supplier_id=$uid":""; $products=mysqli_query($conn,"SELECT p.*,c.name cat FROM products p LEFT JOIN categories c ON c.id=p.category_id $where ORDER BY p.id DESC"); ?>
<div class="row g-4"><div class="col-lg-4"><div class="card-box"><h5>Add Product</h5><form method="POST"><input class="form-control mb-2" name="name" placeholder="Product Name" required><input class="form-control mb-2" name="sku" placeholder="SKU" required><input class="form-control mb-2" name="barcode" placeholder="Barcode Number" required><select class="form-select mb-2" name="category_id"><?php while($c=mysqli_fetch_assoc($cats)){ ?><option value="<?php echo $c['id']; ?>"><?php echo $c['name']; ?></option><?php } ?></select><?php if($_SESSION['role']=='admin'){ ?><select class="form-select mb-2" name="supplier_id"><?php while($s=mysqli_fetch_assoc($suppliers)){ ?><option value="<?php echo $s['id']; ?>"><?php echo $s['name']; ?></option><?php } ?></select><?php } ?><input class="form-control mb-2" name="purchase_price" type="number" step="0.01" placeholder="Purchase Price"><input class="form-control mb-2" name="sale_price" type="number" step="0.01" placeholder="Sale Price"><input class="form-control mb-3" name="gst_percent" type="number" step="0.01" value="18" placeholder="GST %"><button class="btn btn-success" name="add">Save Product</button></form></div></div><div class="col-lg-8"><div class="card-box"><h5>Products</h5><table class="table"><tr><th>Name</th><th>SKU</th><th>Barcode</th><th>Sale</th><th>GST</th><th>Print</th></tr><?php while($p=mysqli_fetch_assoc($products)){ ?><tr><td><?php echo $p['name']; ?></td><td><?php echo $p['sku']; ?></td><td><?php echo $p['barcode']; ?></td><td>₹<?php echo money($p['sale_price']); ?></td><td><?php echo $p['gst_percent']; ?>%</td><td><a class="btn btn-dark btn-sm" target="_blank" href="../barcode.php?id=<?php echo $p['id']; ?>">Barcode</a></td></tr><?php } ?></table></div></div></div><?php include '../includes/footer.php'; ?>
